import assert from 'node:assert/strict';
import test from 'node:test';
import { initialRequestState, requestLifecycleReducer as reduce } from '../src/frontend/request-lifecycle.js';
test('request start records id and epoch and clears the previous error', () => {
  const state = Object.freeze({ ...initialRequestState, error: 'old' });
  const action = Object.freeze({ type: 'request/start', requestId: 'new', epoch: 2 });
  assert.deepEqual(reduce(state, action), { activeRequestId: 'new', connectionEpoch: 2, loading: true, results: [], error: null });
  assert.equal(state.error, 'old'); assert.equal(action.requestId, 'new');
});
test('newer reconnect cancels active work and preserves prior results without mutating state', () => {
  const results = Object.freeze(['prior']);
  const state = Object.freeze({ activeRequestId: 'old', connectionEpoch: 2, loading: true, results, error: 'old error' });
  const actual = reduce(state, Object.freeze({ type: 'connection/reconnect', epoch: 3 }));
  assert.deepEqual(actual, { activeRequestId: null, connectionEpoch: 3, loading: false, results: ['prior'], error: null });
  assert.strictEqual(actual.results, results);
  for (const epoch of [1, 2]) assert.strictEqual(reduce(state, { type: 'connection/reconnect', epoch }), state);
});
test('success and failure require both active id and epoch and ignore duplicate settlement', () => {
  const state = Object.freeze({ activeRequestId: 'current', connectionEpoch: 4, loading: true, results: Object.freeze(['prior']), error: null });
  for (const type of ['request/success', 'request/failure']) {
    for (const [requestId, epoch] of [['stale', 4], ['current', 3], ['current', 5]]) {
      assert.strictEqual(reduce(state, Object.freeze({ type, requestId, epoch, results: ['wrong'], error: 'wrong' })), state);
    }
    const action = Object.freeze({ type, requestId: 'current', epoch: 4, results: Object.freeze(['new']), error: 'failed' });
    const result = reduce(state, action);
    assert.equal(result.activeRequestId, null); assert.equal(result.loading, false);
    assert.equal(result.error, type === 'request/failure' ? 'failed' : null);
    assert.deepEqual(result.results, type === 'request/success' ? ['new'] : ['prior']);
    if (type === 'request/success') assert.notStrictEqual(result.results, action.results);
    assert.strictEqual(reduce(result, action), result);
    assert.deepEqual(state.results, ['prior']); assert.deepEqual(action.results, ['new']);
  }
});
test('superseded starts are ignored and existing unknown-action behavior is preserved', () => {
  const state = reduce(initialRequestState, { type: 'request/start', requestId: 'first', epoch: 2 });
  const newer = reduce(state, { type: 'request/start', requestId: 'second', epoch: 2 });
  assert.strictEqual(reduce(newer, { type: 'request/success', requestId: 'first', epoch: 2, results: [] }), newer);
  assert.strictEqual(reduce(newer, { type: 'request/start', requestId: 'old', epoch: 1 }), newer);
  assert.strictEqual(reduce(newer, { type: 'unknown' }), newer);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { compareSubscriptionContracts as compare } from '../src/fullstack/contract-sync.js';
const backend = () => ({ version: 2, statuses: ['active', 'paused'], requiredFields: ['id', 'status'] });
const frontend = () => ({ version: 2, statuses: ['paused', 'active'], fields: ['status', 'id', 'extra-ui-field'] });
test('equal positive versions and sets are compatible regardless of input ordering', () => {
  assert.deepEqual(compare(backend(), frontend()), { compatible: true, missingStatuses: [], extraStatuses: [], missingFields: [], versionMismatch: false });
  assert.deepEqual(compare({ version: 1, statuses: [], requiredFields: [] }, { version: 1, statuses: [], fields: [] }),
    { compatible: true, missingStatuses: [], extraStatuses: [], missingFields: [], versionMismatch: false });
});
test('missing and extra outputs have correct direction and UTF-8 byte ordering', () => {
  const result = compare({ version: 1, statuses: ['𐀀', '', 'z'], requiredFields: ['𐀀', '', 'a'] },
    { version: 2, statuses: ['𐀁', '', 'b'], fields: ['not-required'] });
  assert.deepEqual(result, { compatible: false, missingStatuses: ['z', '', '𐀀'], extraStatuses: ['b', '', '𐀁'],
    missingFields: ['a', '', '𐀀'], versionMismatch: true });
});
test('each mismatch alone makes contracts incompatible', () => {
  for (const change of [{ version: 3 }, { statuses: ['active'] }, { statuses: ['active', 'paused', 'extra'] }, { fields: ['id'] }]) {
    assert.equal(compare(backend(), { ...frontend(), ...change }).compatible, false);
  }
});
test('malformed contracts and nonpositive or noninteger versions throw TypeError', () => {
  for (const bad of [null, undefined, 'bad', 7, {}]) {
    assert.throws(() => compare(bad, frontend()), TypeError); assert.throws(() => compare(backend(), bad), TypeError);
  }
  for (const version of [0, -1, 1.5, '2', NaN, Infinity]) {
    assert.throws(() => compare({ ...backend(), version }, frontend()), TypeError);
    assert.throws(() => compare(backend(), { ...frontend(), version }), TypeError);
  }
});
test('all four declaration arrays require unique non-empty strings', () => {
  for (const bad of [undefined, null, 'active', [1], [''], ['same', 'same']]) {
    for (const key of ['statuses', 'requiredFields']) assert.throws(() => compare({ ...backend(), [key]: bad }, frontend()), TypeError);
    for (const key of ['statuses', 'fields']) assert.throws(() => compare(backend(), { ...frontend(), [key]: bad }), TypeError);
  }
});
test('comparison returns fresh output and never mutates inputs', () => {
  const left = backend(), right = frontend(), before = structuredClone([left, right]);
  Object.freeze(left.statuses); Object.freeze(left.requiredFields); Object.freeze(left);
  Object.freeze(right.statuses); Object.freeze(right.fields); Object.freeze(right);
  const result = compare(left, right), again = compare(left, right);
  assert.notStrictEqual(result, again); assert.notStrictEqual(result.missingStatuses, again.missingStatuses);
  result.missingStatuses.push('changed-output'); assert.deepEqual([left, right], before);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { billingBucket } from '../src/backend/billing-window.js';
const period = (changes = {}) => ({ startsAt: 10, endsAt: 20, maxClockSkewMs: 2, ...changes });
const event = (changes = {}) => ({ occurredAt: 10, receivedAt: 10, ...changes });
test('billing occurrences use the half-open period boundaries', () => {
  assert.equal(billingBucket(event({ occurredAt: 9 }), period()), 'outside');
  assert.equal(billingBucket(event(), period()), 'current');
  assert.equal(billingBucket(event({ occurredAt: 19, receivedAt: 19 }), period()), 'current');
  assert.equal(billingBucket(event({ occurredAt: 20, receivedAt: 20 }), period()), 'outside');
});
test('clock skew and late receipt have their exact inclusive and exclusive boundaries', () => {
  assert.equal(billingBucket(event({ receivedAt: 8 }), period()), 'current');
  assert.equal(billingBucket(event({ receivedAt: 7 }), period()), 'invalid-clock');
  assert.equal(billingBucket(event({ receivedAt: 21 }), period()), 'current');
  assert.equal(billingBucket(event({ receivedAt: 22 }), period()), 'late');
  assert.equal(billingBucket(event({ receivedAt: 23 }), period()), 'late');
  assert.equal(billingBucket(event({ receivedAt: 9 }), period({ maxClockSkewMs: 0 })), 'invalid-clock');
  assert.equal(billingBucket(event({ receivedAt: 20 }), period({ maxClockSkewMs: 0 })), 'late');
});
test('outside occurrence takes precedence and negative integer timestamps remain valid', () => {
  assert.equal(billingBucket(event({ occurredAt: 9, receivedAt: 0 }), period()), 'outside');
  assert.equal(billingBucket(event({ occurredAt: 20, receivedAt: 100 }), period()), 'outside');
  assert.equal(billingBucket({ occurredAt: -5, receivedAt: -5 }, { startsAt: -10, endsAt: 0, maxClockSkewMs: 0 }), 'current');
});
test('each time and skew field must be finite integer and the period must increase', () => {
  for (const invalid of [NaN, Infinity, -Infinity, 0.5, '10', null, undefined]) {
    for (const field of ['occurredAt', 'receivedAt']) assert.throws(() => billingBucket(event({ [field]: invalid }), period()), TypeError);
    for (const field of ['startsAt', 'endsAt', 'maxClockSkewMs']) assert.throws(() => billingBucket(event(), period({ [field]: invalid })), TypeError);
  }
  assert.throws(() => billingBucket(event(), period({ maxClockSkewMs: -1 })), TypeError);
  assert.throws(() => billingBucket(event(), period({ endsAt: 10 })), TypeError);
  assert.throws(() => billingBucket(event(), period({ endsAt: 9 })), TypeError);
  for (const invalid of [null, undefined, 1, '', {}]) {
    assert.throws(() => billingBucket(invalid, period()), TypeError);
    assert.throws(() => billingBucket(event(), invalid), TypeError);
  }
});
test('all outcomes and validation failures leave event and period unchanged', () => {
  for (const changes of [{}, { occurredAt: 9 }, { receivedAt: 7 }, { receivedAt: 22 }, { receivedAt: '10' }]) {
    const input = event(changes), window = period(), before = structuredClone([input, window]);
    if (typeof input.receivedAt === 'string') assert.throws(() => billingBucket(input, window), TypeError);
    else billingBucket(input, window);
    assert.deepEqual([input, window], before);
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { retry } from '../src/reliability/retry.js';
test('success returns the actual value without sleeping or making another attempt', async () => {
  let calls = 0; const result = { ok: true }, delays = [];
  assert.strictEqual(await retry(() => { calls++; return result; }, { maxAttempts: 3, baseDelayMs: 4, sleep: async ms => delays.push(ms) }), result);
  assert.equal(calls, 1); assert.deepEqual(delays, []);
});
test('sleep is awaited between failures and exponential delays precede the next attempt', async () => {
  let calls = 0, pendingSleep = false; const delays = [], order = [];
  const result = await retry(async () => {
    assert.equal(pendingSleep, false); calls++; order.push('attempt-' + calls);
    if (calls < 3) throw new Error('temporary'); return 'done';
  }, { maxAttempts: 4, baseDelayMs: 5, sleep: async ms => {
    pendingSleep = true; delays.push(ms); order.push('sleep-' + ms); await Promise.resolve(); pendingSleep = false;
  } });
  assert.equal(result, 'done'); assert.equal(calls, 3); assert.deepEqual(delays, [5, 10]);
  assert.deepEqual(order, ['attempt-1', 'sleep-5', 'attempt-2', 'sleep-10', 'attempt-3']);
});
test('the final error is rethrown unchanged and no sleep follows the last failed attempt', async () => {
  let calls = 0; const errors = [new Error('first'), new Error('last')], delays = [];
  await assert.rejects(retry(() => { throw errors[calls++]; }, { maxAttempts: 2, baseDelayMs: 3, sleep: async ms => delays.push(ms) }), error => error === errors[1]);
  assert.equal(calls, 2); assert.deepEqual(delays, [3]);
});
test('invalid positive-integer attempt limits throw TypeError before operation or sleep', async () => {
  for (const maxAttempts of [0, -1, 1.5, NaN, Infinity, '2']) {
    let calls = 0, sleeps = 0;
    await assert.rejects(retry(() => { calls++; }, { maxAttempts, baseDelayMs: 1, sleep: async () => { sleeps++; } }), TypeError);
    assert.equal(calls, 0); assert.equal(sleeps, 0);
  }
});
test('invalid delay and sleep options reject before the operation runs', async () => {
  for (const baseDelayMs of [-1, NaN, Infinity, '1']) {
    let calls = 0, sleeps = 0;
    await assert.rejects(retry(() => { calls++; }, { maxAttempts: 2, baseDelayMs, sleep: async () => { sleeps++; } }), TypeError);
    assert.equal(calls, 0); assert.equal(sleeps, 0);
  }
  for (const sleep of [false, 0, {}, 'sleep']) {
    let calls = 0;
    await assert.rejects(retry(() => { calls++; }, { maxAttempts: 2, baseDelayMs: 1, sleep }), TypeError);
    assert.equal(calls, 0);
  }
});
test('a representable positive integer beyond the safe-integer range permits immediate success', async () => {
  let calls = 0;
  assert.equal(await retry(() => { calls++; return 'done'; }, { maxAttempts: 2 ** 54, baseDelayMs: 1, sleep: async () => assert.fail('unexpected sleep') }), 'done');
  assert.equal(calls, 1);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { parseNdjsonChunks } from '../src/data/ndjson-stream.js';
const encode = value => new TextEncoder().encode(value);
test('incremental UTF-8 preserves records across every split and a final record without newline', () => {
  const bytes = encode('{"text":"Việt 😀"}\r\n\n{"n":2}');
  for (let cut = 0; cut <= bytes.length; cut++) {
    assert.deepEqual(parseNdjsonChunks([bytes.slice(0, cut), bytes.slice(cut)]), [{ text: 'Việt 😀' }, { n: 2 }]);
  }
  assert.deepEqual(parseNdjsonChunks(Array.from(bytes, byte => new Uint8Array([byte]))), [{ text: 'Việt 😀' }, { n: 2 }]);
});
test('LF and CRLF empty physical lines are ignored and record order is retained', () => {
  assert.deepEqual(parseNdjsonChunks([encode('\n\r\n{"n":1}\n\n{"n":2}\r\n')]), [{ n: 1 }, { n: 2 }]);
  assert.deepEqual(parseNdjsonChunks([]), []);
});
test('non-byte chunks throw TypeError while invalid UTF-8 and invalid JSON throw', () => {
  for (const chunk of ['{}', null, {}, [123, 125], new ArrayBuffer(2)]) {
    assert.throws(() => parseNdjsonChunks([chunk]), TypeError);
  }
  assert.throws(() => parseNdjsonChunks([new Uint8Array([0xff])]));
  assert.throws(() => parseNdjsonChunks([new Uint8Array([0xe2, 0x82])]));
  assert.throws(() => parseNdjsonChunks([encode('{bad}\n')]));
});
test('the chunk array, byte views and backing buffers are not mutated', () => {
  const backing = encode('x{"n":1}\ny'), first = backing.subarray(1, backing.length - 1);
  const second = encode('{"n":2}'), chunks = [first, second];
  const before = [Array.from(backing), Array.from(second)];
  const beforeChunks = [...chunks];
  assert.deepEqual(parseNdjsonChunks(chunks), [{ n: 1 }, { n: 2 }]);
  assert.equal(chunks.length, beforeChunks.length);
  assert.deepEqual(chunks, beforeChunks);
  assert.strictEqual(chunks[0], first); assert.strictEqual(chunks[1], second);
  assert.deepEqual([Array.from(backing), Array.from(second)], before);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { parseArgs } from '../src/platform/args.js';
test('both value syntaxes, adjacent boolean flags and repeated last value', () => {
  assert.deepEqual(parseArgs(['--name', 'first', '--enabled', '--verbose', '--name=last', 'tail']),
    { flags: { name: 'last', enabled: true, verbose: true }, positional: ['tail'] });
  assert.deepEqual(parseArgs(['--empty=']), { flags: { empty: '' }, positional: [] });
  assert.deepEqual(parseArgs(['--name=value=rest']), { flags: { name: 'value=rest' }, positional: [] });
});
test('first standalone terminator makes every later token positional', () => {
  assert.deepEqual(parseArgs(['--mode=one', '--', '--mode=two', '--flag', 'tail', '--']),
    { flags: { mode: 'one' }, positional: ['--mode=two', '--flag', 'tail', '--'] });
  assert.deepEqual(parseArgs(['--', '--flag']), { flags: {}, positional: ['--flag'] });
  assert.deepEqual(parseArgs(['--flag', '--', '--name=x']), { flags: { flag: true }, positional: ['--name=x'] });
});
test('input argv remains unchanged and empty input preserves result shape', () => {
  const argv = ['--a', 'one', '--', '--b']; const before = [...argv];
  assert.deepEqual(parseArgs(argv), { flags: { a: 'one' }, positional: ['--b'] });
  assert.deepEqual(argv, before);
  assert.deepEqual(parseArgs([]), { flags: {}, positional: [] });
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { resolveConfig } from '../src/platform/config.js';
test('each key independently follows CLI then environment then file then defaults', () => {
  assert.deepEqual(resolveConfig({ port: 1 }, { port: 2, debug: false }, { port: 3, debug: true, label: 'file' },
    { port: 4, debug: true, label: 'default' }), { port: 1, debug: false, label: 'file' });
  assert.deepEqual(resolveConfig(), { port: undefined, debug: undefined, label: undefined });
});
test('only undefined is absent at every precedence tier', () => {
  for (const key of ['port', 'debug', 'label']) for (const value of [false, 0, '', null]) {
    for (let chosen = 0; chosen < 4; chosen++) {
      const inputs = Array.from({ length: 4 }, (_, index) => Object.freeze({ [key]: index < chosen ? undefined : index === chosen ? value : 'fallback' }));
      const before = structuredClone(inputs), actual = resolveConfig(...inputs);
      assert.strictEqual(actual[key], value); assert.deepEqual(inputs, before);
    }
  }
});
test('resolution returns a fresh object and leaves all input objects unchanged', () => {
  const inputs = [{ port: 0 }, { debug: false }, { label: '' }, { port: 9, label: 'default' }], before = structuredClone(inputs);
  const actual = resolveConfig(...inputs); actual.port = 999;
  assert.deepEqual(inputs, before); for (const input of inputs) assert.notStrictEqual(actual, input);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { isExpired } from '../src/reliability/expiry.js';
test('expiry is inclusive for both supported representations', () => {
  const iso = '1970-01-01T00:00:01.000Z', date = new Date(1000);
  assert.equal(isExpired(iso, 999), false);
  assert.equal(isExpired(iso, 1000), true);
  assert.equal(isExpired(iso, 1001), true);
  assert.equal(isExpired(date, new Date(999)), false);
  assert.equal(isExpired(date, new Date(1000)), true);
  assert.equal(isExpired(date, new Date(1001)), true);
});
test('ISO offsets and fractional seconds identify the actual instant', () => {
  assert.equal(isExpired('2024-03-01T00:30:00+01:00', Date.parse('2024-02-29T23:30:00Z')), true);
  assert.equal(isExpired('2024-02-29T23:30:00-01:00', Date.parse('2024-03-01T00:30:00Z') - 1), false);
  assert.equal(isExpired('1970-01-01T00:00:00.001Z', 0), false);
  assert.equal(isExpired('1970-01-01T00:00:00.001Z', 1), true);
});
test('explicit falsey now never consults the current clock', () => {
  const original = Date.now;
  Date.now = () => { throw new Error('machine clock must not be used'); };
  try {
    assert.equal(isExpired('1970-01-01T00:00:01Z', 0), false);
    assert.equal(isExpired('1970-01-01T00:00:00Z', -0), true);
    for (const now of [undefined, null, false, '', NaN]) {
      assert.throws(() => isExpired('1970-01-01T00:00:01Z', now), TypeError);
    }
  } finally { Date.now = original; }
});
test('invalid dates and unsupported input types throw TypeError', () => {
  for (const expiresAt of [new Date(NaN), '', 'not-a-date', '2023-02-29T00:00:00Z',
    '2024-02-30T00:00:00Z', '2024-13-01T00:00:00Z', '2024-01-01T25:00:00Z', null, undefined, 0]) {
    assert.throws(() => isExpired(expiresAt, 0), TypeError);
  }
  for (const now of [new Date(NaN), Infinity, -Infinity, '1000', {}, []]) {
    assert.throws(() => isExpired('1970-01-01T00:00:01Z', now), TypeError);
  }
});
test('omitted now preserves arity and reads the clock after expiry validation', () => {
  const original = Date.now; let reads = 0;
  Date.now = () => { reads += 1; return 1000; };
  try {
    assert.equal(isExpired.length, 1);
    assert.equal(isExpired('1970-01-01T00:00:01.000Z'), true);
    assert.equal(reads, 1);
    assert.equal(isExpired('1970-01-01T00:00:01.001Z'), false);
    assert.equal(reads, 2);
    assert.throws(() => isExpired(new Date(NaN)), TypeError);
    assert.equal(reads, 2);
    assert.throws(() => isExpired('1970-01-01T00:00:01.000Z', undefined), TypeError);
    assert.equal(reads, 2);
  } finally { Date.now = original; }
});
test('Date input values remain unchanged', () => {
  const expiry = new Date(1000), now = new Date(999);
  assert.equal(isExpired(expiry, now), false);
  assert.equal(expiry.getTime(), 1000);
  assert.equal(now.getTime(), 999);
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { replayVersionedEvents } from '../src/data/versioned-replay.js';
const state = () => ({ entities: {}, appliedEventIds: [] });
const event = (overrides = {}) => ({ eventId: 'first', entityId: 'entity', expectedVersion: 0, nextValue: { count: 1 }, ...overrides });
test('missing entities start at zero, accepted events advance once and applied order is retained', () => {
  const input = state(), events = [event(), event({ eventId: 'second', expectedVersion: 1, nextValue: { count: 2 } })];
  const before = structuredClone([input, events]);
  const result = replayVersionedEvents(input, events);
  assert.deepEqual(result, { entities: { entity: { version: 2, value: { count: 2 } } }, appliedEventIds: ['first', 'second'] });
  assert.notStrictEqual(result, input); assert.deepEqual([input, events], before);
  result.entities.entity.value.count = 9; assert.deepEqual([input, events], before);
});
test('duplicates in a replay and previously applied event ids are idempotent no-ops', () => {
  let once;
  assert.doesNotThrow(() => { once = replayVersionedEvents(state(), [event(), event()]); });
  assert.deepEqual(once, { entities: { entity: { version: 1, value: { count: 1 } } }, appliedEventIds: ['first'] });
  let twice;
  assert.doesNotThrow(() => { twice = replayVersionedEvents(once, [event()]); });
  assert.deepEqual(twice, once); assert.notStrictEqual(twice, once);
});
test('nonduplicate version conflicts contain version conflict without partially mutating input', () => {
  const input = state(), events = [event(), event({ eventId: 'conflicting', expectedVersion: 0 })];
  const before = structuredClone([input, events]);
  assert.throws(() => replayVersionedEvents(input, events), /version conflict/);
  assert.deepEqual([input, events], before);
});
test('malformed state or event shapes and empty IDs throw TypeError', () => {
  for (const input of [null, [], {}, { entities: null, appliedEventIds: [] }, { entities: {}, appliedEventIds: '' },
    { entities: {}, appliedEventIds: [''] }]) assert.throws(() => replayVersionedEvents(input, []), TypeError);
  for (const bad of [null, [], {}, event({ eventId: '' }), event({ eventId: 1 }), event({ entityId: '' }),
    event({ entityId: null }), event({ expectedVersion: 0.5 }), event({ expectedVersion: '0' })]) {
    assert.throws(() => replayVersionedEvents(state(), [bad]), TypeError);
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { invoiceTotalCents } from '../src/backend/invoice.js';
test('omitted quantity defaults to one and omitted discount and tax default to zero', () => {
  assert.equal(invoiceTotalCents([{ unitCents: 101 }]), 101);
  assert.equal(invoiceTotalCents([{ unitCents: 101, quantity: 3 }]), 303);
  assert.equal(invoiceTotalCents([]), 0);
});
test('quantity multiplication precedes discount and each line rounds before summation', () => {
  assert.equal(invoiceTotalCents([{ unitCents: 101, quantity: 3, discountBps: 2500 }]), 227);
  assert.equal(invoiceTotalCents([{ unitCents: 1, discountBps: 5000 },
    { unitCents: 1, discountBps: 5000 }]), 2);
});
test('tax applies once after rounded line totals and the invoice rounds once more', () => {
  assert.equal(invoiceTotalCents([{ unitCents: 1 }, { unitCents: 1 }, { unitCents: 1 }], 5000), 5);
  assert.equal(invoiceTotalCents([{ unitCents: 199, quantity: 2, discountBps: 1250 }], 825), 377);
});
test('zero money and inclusive basis point endpoints are valid', () => {
  assert.equal(invoiceTotalCents([{ unitCents: 0, quantity: 1, discountBps: 0 }], 0), 0);
  assert.equal(invoiceTotalCents([{ unitCents: 99, quantity: 1, discountBps: 10000 }], 10000), 0);
  assert.equal(invoiceTotalCents([{ unitCents: 101, quantity: 1, discountBps: 0 }], 10000), 202);
});
test('negative and non-integer money or quantity throws TypeError and quantity is positive', () => {
  for (const unitCents of [-1, 0.5, NaN, Infinity, '1', null]) {
    assert.throws(() => invoiceTotalCents([{ unitCents, quantity: 1 }]), TypeError);
  }
  for (const quantity of [0, -1, 0.5, NaN, Infinity, '1']) {
    assert.throws(() => invoiceTotalCents([{ unitCents: 1, quantity }]), TypeError);
  }
});
test('discount and tax reject values outside the inclusive integer basis point range', () => {
  for (const invalid of [-1, 10001, 0.5, NaN, Infinity, '1']) {
    assert.throws(() => invoiceTotalCents([{ unitCents: 1, discountBps: invalid }]), TypeError);
    assert.throws(() => invoiceTotalCents([{ unitCents: 1 }], invalid), TypeError);
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { pageCount, clampPage } from '../src/frontend/pagination.js';
test('public pagination contract', () => {
  assert.equal(pageCount(0, 5), 0);
  assert.equal(pageCount(10, 5), 2);
  assert.equal(pageCount(11, 5), 3);
  assert.equal(pageCount(2 ** 53, 1), 2 ** 53);
  assert.equal(pageCount(1, 2 ** 53), 1);
  assert.equal(pageCount(2 ** 54, 3), 6004799503160661);
  assert.equal(pageCount(2 ** 55, 3), 12009599006321322);
  assert.equal(clampPage(2 ** 54, 2 ** 54, 3), 6004799503160661);
